module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [3:0] pattern;
    reg [3:0] shift_reg;
    reg [31:0] counter;
    reg counting_up;
    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter WAIT1 = 2'b01;
    parameter WAIT2 = 2'b10;
