module FSM (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] count;
    reg [3:0] pattern;
    always @(*) begin
        case (state)
            3'b000: next_state = (pattern == 4'b1101) ? 3'b001 : 3'b000;
            3'b001: next_state = (count == 4) ? 3'b010 : 3'b001;
            3'b010: next_state = (done_counting) ? 3'b011 : 3'b010;
            3'b011: next_state = (ack) ? 3'b000 : 3'b011;
            default: next_state = 3'b000;
        endcase
    end
