            state <= next_state;
            case (state)
                3'b000: begin
                    shift_ena <= 1'b0;
                    counting <= 1'b0;
                    done <= 1'b0;
                    if (data) pattern <= {pattern[2:0], 1'b1};
                    else pattern <= {pattern[2:0], 1'b0};
