                    shift_ena <= 1'b1;
                    counting <= 1'b0;
                    done <= 1'b0;
                    if (count == 4) shift_ena <= 1'b0;
                    count <= count + 1;
                end
                3'b010: begin
                    shift_ena <= 1'b0;
                    counting <= 1'b1;
                    done <= 1'b0;
                end
                3'b011: begin
                    shift_ena <= 1'b0;
                    counting <= 1'b0;
                    done <= 1'b1;
                    if (~ack) done <= 1'b0;
                end
            endcase
        end
    end
