// Timer FSM: implements the time-out sequence (1101) plus a delay determined
// by another 4 bits. The counting signal is asserted for one clock cycle
// after the delay time, to wait for the counters to finish counting.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [3:0] shift_reg;
    reg [3:0] delay;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'd0;
            delay <= 4'd0;
            state <= 2'd0;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'd0: begin // wait for 1101
                    if (data && shift_reg == 4'd1) shift_ena <= 1'b1;
                    if (shift_ena) begin
                        if (delay == 4'd0) counting <= 1'b1;
                        shift_ena <= 1'b0;
                        state <= 2'd1;
                    end
                    shift_reg <= {data, shift_reg[3:1]};
                end
                2'd1: begin // wait for done_counting
                    if (done_counting) begin
                        counting <= 1'b0;
                        delay <= shift_reg;
                        state <= 2'd2;
                    end
                end
                2'd2: begin // wait for ack
                    if (ack) begin
                        done <= 1'b1;
                        state <= 2'd3;
                    end
                end
                2'd3: begin // wait for ack, then go back to 0
                    if (ack) begin
                        done <= 1'b0;
                        state <= 2'd0;
                    end
                end
            endcase
        end
    end
endmodule

