// One-bit timer: starts, waits, counts, notifies, resets.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] bit_count;
    reg [3:0] next_bit_count;
    reg [3:0] delay;
    reg [3:0] next_delay;
    wire pattern_detected;
    wire start_timer;
    wire counted_and_acked;
    reg delayed;
    reg next_delayed;
    always @(*) begin
        pattern_detected = (state == 3'b000) && data;
        start_timer = pattern_detected && (bit_count == 3'b110);
        counted_and_acked = done_counting && ack;
        next_state = state;
        next_bit_count = bit_count;
        next_delay = delay;
        next_delayed = delayed;
        case (state)
            3'b000: begin
                if (pattern_detected) next_state = 3'b001;
            end
            3'b001: begin
                next_state = 3'b010;
                next_delay = 4;
            end
            3'b010: begin
                if (delayed) next_state = 3'b011;
            end
            3'b011: begin
                if (counted_and_acked) begin
                    next_state = 3'b100;
                    done = 1;
                end
            end
            3'b100: begin
                if (!ack) next_state = 3'b000;
            end
        endcase
        if (start_timer) next_delay = 0;
        if (delay > 0) next_delay = delay - 1;
        if (start_timer) shift_ena = 1;
        if (counted_and_acked) done = 0;
        if (start_timer) counting = 1;
        if (counted_and_acked) counting = 0;
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            bit_count <= 3'b000;
            delay <= 3'b000;
            delayed <= 0;
            shift_ena <= 0;
            counting <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            bit_count <= next_bit_count;
            delay <= next_delay;
            delayed <= next_delayed;
            if (start_timer) next_bit_count <= 3'b000;
            else if (shift_ena) next_bit_count <= bit_count + 1;
            if (start_timer) next_delayed <= 1;
            else if (delay == 0) next_delayed <= 0;
        end
    end
endmodule

