// Timer FSM. Implements a timer that is started when a particular pattern
// (1101) is detected, shifts in 4 more bits to determine the duration to delay,
// waits for the counters to finish counting, and notifies the user.
module TopModule_TimerFSM (
  input clk,
  input reset,
  input data,
  input done_counting,
  input ack,
  output reg shift_ena,
  output reg counting,
  output reg done
);
  reg [2:0] state;
  reg [15:0] count;
  reg [15:0] delay;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b0;
      count <= 16'd0;
      delay <= 16'd0;
    end else begin
      case (state)
        3'b000: begin // Wait for start pattern (1101)
          if (data) state <= 3'b001;
        end
        3'b001: begin // Assert shift_ena for 4 cycles
          if (count == 16'd4) begin
            state <= 3'b010;
            count <= 16'd0;
          end else begin
            count <= count + 16'd1;
          end
          shift_ena <= 1'b1;
        end
        3'b010: begin // Wait for counters to finish counting
          if (done_counting) begin
            state <= 3'b011;
            counting <= 1'b1;
          end
        end
        3'b011: begin // Wait for ack and notify the user
          if (ack) begin
            state <= 3'b000;
            done <= 1'b1;
          end
        end
      endcase
    end
  end
  // Register the 4-bit delay value (concatenated with the start pattern)
  always @(posedge clk) begin
    if (reset) delay <= 16'd0;
    else if (state == 3'b001 && count == 16'd4) delay <= {1'b1, 1'b1, 1'b0, 1'b1, data};
